+    @Test
+    void blocksConfirmationWithInvalidEmail() throws Exception {
+        String invalidEmailJson = RESERVATION_JSON.replace("carla@example.com", "carla@invalid");
+        long id = json.readTree(post("/reservations", invalidEmailJson).body()).get("id").asLong();
+        assertEquals(200, post("/reservations/" + id + "/confirmation", "").statusCode());
+
+        JsonNode messages = json.readTree(get("/messages").body());
+        assertEquals(1, messages.size());
+        assertEquals("BLOCKED", messages.get(0).get("status").asText());
+        assertEquals("carla@invalid", messages.get(0).get("to").asText());
+    }
 }
