    26	    Message add(String channel, String to, String subject, String body) {
    27	        return addProcessed(channel, to, subject, body);
    28	    }
    29	
    30	    private Message addProcessed(String channel, String to, String subject, String body) {
    31	        if (!EmailValidator.isValid(to)) {
    32	            return addBlocked(channel, to, subject, body);
    33	        }
    34	
    35	        if (rules.isTestMode()) {
    36	            return addTestMode(channel, to, subject, body);
    37	        }
    38	
    39	        Message sent = insertMessage(channel, to, subject, body, "SENT");
    40	        insertMessage(channel, "arquivo@pousadamarealta.com.br", "[Cópia] " + subject, body, "SENT");
    41	        return sent;
    42	    }
    43	
    44	    private Message addBlocked(String channel, String to, String subject, String body) {
    45	        return insertMessage(channel, to, subject, body, "BLOCKED");
    46	    }
    47	
    48	    private Message addTestMode(String channel, String to, String subject, String body) {
    49	        String testBody = "Destinatário original: " + to + "\n" + body;
    50	        return insertMessage(channel, "testes@pousadamarealta.com.br", "[TESTE] " + subject, testBody, "SENT");
    51	    }
    52	
    53	    private Message insertMessage(String channel, String to, String subject, String body, String status) {
    54	        try (Connection connection = dataSource.getConnection();
    55	                PreparedStatement insert = connection.prepareStatement(
    56	                        "INSERT INTO messages (channel, recipient, subject, body, status) VALUES (?, ?, ?, ?, ?) RETURNING id")) {
    57	            insert.setString(1, channel);
    58	            insert.setString(2, to);
    59	            insert.setString(3, subject);
    60	            insert.setString(4, body);
    61	            insert.setString(5, status);
    62	            try (ResultSet generated = insert.executeQuery()) {
    63	                generated.next();
    64	                return new Message(generated.getLong("id"), channel, to, subject, body, status);
    65	            }
    66	        } catch (SQLException failure) {
    67	            throw new IllegalStateException("could not keep the message to " + to, failure);
    68	        }
    69	    }
    70	
    71	    public List<Message> all() {
    72	        try (Connection connection = dataSource.getConnection();
    73	                PreparedStatement select = connection.prepareStatement(
    74	                        "SELECT id, channel, recipient, subject, body, status FROM messages ORDER BY id");
    75	                ResultSet rows = select.executeQuery()) {
    76	            List<Message> messages = new ArrayList<>();
    77	            while (rows.next()) {
    78	                messages.add(new Message(
    79	                        rows.getLong("id"),
    80	                        rows.getString("channel"),
    81	                        rows.getString("recipient"),
    82	                        rows.getString("subject"),
    83	                        rows.getString("body"),
    84	                        rows.getString("status")));
    85	            }
    86	            return messages;
    87	        } catch (SQLException failure) {
    88	            throw new IllegalStateException("could not read the sent messages", failure);
    89	        }
    90	    }
    91	}

